auto func (auto value){  
    int count = 0;  
    for(auto c : value) {  
        if(isalpha(c)) count++;  
    }  
    return count;  
}

auto func (auto value){  
    int count = 0;  
    for(auto c : value) {  
        if(isdigit(c)) count++;  
    }  
    return count;  
}

auto func (auto value){ 
    int count = 0;
    for(auto& c : value){
        if(isalpha(c)) ++count;
    }
    return count;
}
